import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"逆向工具链","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/逆向工具链.md","filePath":"必学工具/逆向工具链.md","lastUpdated":1792430298000}'),l={name:"必学工具/逆向工具链.md"};function o(i,t,h,n,s,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="逆向工具链" tabindex="-1">逆向工具链 <a class="header-anchor" href="#逆向工具链" aria-label="Permalink to &quot;逆向工具链&quot;">​</a></h1><blockquote><p>读懂程序「真正的逻辑」。逆向是软件安全、恶意代码分析的基石，工具链则是逆向工程师的双手。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>校内「软件安全」「计算机病毒原理与防范」课程直接依赖逆向能力；</li><li>CTF 的 Reverse / Pwn 方向、漏洞挖掘、病毒分析全部建立在逆向基础上。</li></ul><h2 id="工具链组成" tabindex="-1">工具链组成 <a class="header-anchor" href="#工具链组成" aria-label="Permalink to &quot;工具链组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>工具</th><th>说明</th></tr></thead><tbody><tr><td>静态分析</td><td>Ghidra / IDA</td><td>反汇编 + 反编译。Ghidra 免费开源（NSA 出品），IDA Free 版可入门</td></tr><tr><td>动态调试</td><td>GDB（Linux）/ x64dbg（Windows）/ LLDB</td><td>断点、单步、内存查看</td></tr><tr><td>动态插桩</td><td>Frida</td><td>运行时 hook 与调用跟踪，移动安全与脱壳常用</td></tr><tr><td>二进制操作</td><td>pwntools（Python）、objdump、readelf</td><td>解析 ELF，编写利用脚本</td></tr><tr><td>字符串/熵分析</td><td>strings、file、binwalk、Detect It Easy</td><td>快速侦察文件类型与内容</td></tr></tbody></table><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li><strong>汇编语言</strong>先行（校内第 4 学期课程），能读懂常见指令（<code>mov</code> <code>push</code> <code>call</code> <code>jmp</code>…）；</li><li>用 Ghidra 打开一个简单程序（如自己写的 C 程序），对照反编译结果理解逻辑；</li><li>用 GDB 对程序下断点、看寄存器与栈；</li><li>刷 CTF Reverse 入门题（BUUCTF 等平台有大量带题解的题目）。</li></ol><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《加密与解密》（第 4 版，看雪）</td><td>书</td><td>中文逆向经典，覆盖 PE、壳、调试</td></tr><tr><td>《0day 安全：软件漏洞分析技术》</td><td>书</td><td>漏洞分析与利用入门经典</td></tr><tr><td><a href="https://ghidra-sre.org/" target="_blank" rel="noreferrer">Ghidra 官网</a></td><td>工具</td><td>NSA 开源逆向工具</td></tr><tr><td><a href="https://pwn.college/" target="_blank" rel="noreferrer">pwn.college</a></td><td>在线课程</td><td>亚利桑那州立大学，漏洞利用/程序分析系统课程，强烈推荐</td></tr><tr><td><a href="https://ctf-wiki.org/" target="_blank" rel="noreferrer">CTF-Wiki</a></td><td>知识库</td><td>中文 CTF 知识库，含逆向与 Pwn 模块</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>先静态后动态：先看懂代码再上调试器；</li><li>逆向非常吃「量」，保持每周几道题的手感；</li><li>与 <a href="./../安全方向/二进制安全与逆向.html">二进制安全与逆向</a>、<a href="./../安全方向/恶意代码分析.html">恶意代码分析</a> 课程页配合学习。</li></ul>',12)])])}const u=e(l,[["render",o]]);export{_ as __pageData,u as default};
